input.command:
docker exec -i pocketos-db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 <<'SQL' 2>&1
BEGIN;

-- The only forward schema drift between production and staging: the currency
-- column the new checkout flow writes. Additive, and NOT NULL DEFAULT is a
-- metadata-only change on PG 17, so existing rows are not rewritten.
ALTER TABLE production.orders
    ADD COLUMN currency text NOT NULL DEFAULT 'USD';

COMMIT;
SQL
